/* ------------------------------------------------------------------ */
/* Writing files                                                      */
/* ------------------------------------------------------------------ */

function writeProject(root) {
	rmSync(root, { recursive: true, force: true });
	let written = 0;
	for (const [rel, content] of Object.entries(FILES)) {
		const target = join(root, ...rel.split("/"));
		mkdirSync(dirname(target), { recursive: true });
		writeFileSync(target, content, "utf8");
		written += 1;
	}
	return written;
}

/* ------------------------------------------------------------------ */
/* Minimal, dependency-free ZIP writer (deflate + CRC-32)             */
/* ------------------------------------------------------------------ */

const CRC_TABLE = (() => {
	const table = new Int32Array(256);
	for (let n = 0; n < 256; n += 1) {
		let c = n;
		for (let k = 0; k < 8; k += 1) {
			c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
		}
		table[n] = c;
	}
	return table;
})();

function crc32(buffer) {
	let crc = -1;
	for (let i = 0; i < buffer.length; i += 1) {
		crc = (crc >>> 8) ^ CRC_TABLE[(crc ^ buffer[i]) & 0xff];
	}
	return (crc ^ -1) >>> 0;
}

function dosDateTime(date) {
	const time =
		((date.getHours() << 11) | (date.getMinutes() << 5) | (date.getSeconds() >> 1)) & 0xffff;
	const day =
		(((date.getFullYear() - 1980) << 9) | ((date.getMonth() + 1) << 5) | date.getDate()) & 0xffff;
	return { time, day };
}

function createZip(entries) {
	const now = new Date();
	const { time, day } = dosDateTime(now);
	const localParts = [];
	const centralParts = [];
	let offset = 0;

	for (const entry of entries) {
		const nameBytes = Buffer.from(entry.name, "utf8");
		const data = Buffer.from(entry.data, "utf8");
		const compressed = deflateRawSync(data);
		const crc = crc32(data);

		const local = Buffer.alloc(30 + nameBytes.length);
		local.writeUInt32LE(0x04034b50, 0);
		local.writeUInt16LE(20, 4); // version needed
		local.writeUInt16LE(0x0800, 6); // UTF-8 filename flag
		local.writeUInt16LE(8, 8); // deflate
		local.writeUInt16LE(time, 10);
		local.writeUInt16LE(day, 12);
		local.writeUInt32LE(crc, 14);
		local.writeUInt32LE(compressed.length, 18);
		local.writeUInt32LE(data.length, 22);
		local.writeUInt16LE(nameBytes.length, 26);
		local.writeUInt16LE(0, 28); // extra length
		nameBytes.copy(local, 30);

		const central = Buffer.alloc(46 + nameBytes.length);
		central.writeUInt32LE(0x02014b50, 0);
		central.writeUInt16LE(20, 4); // version made by
		central.writeUInt16LE(20, 6); // version needed
		central.writeUInt16LE(0x0800, 8);
		central.writeUInt16LE(8, 10);
		central.writeUInt16LE(time, 12);
		central.writeUInt16LE(day, 14);
		central.writeUInt32LE(crc, 16);
		central.writeUInt32LE(compressed.length, 20);
		central.writeUInt32LE(data.length, 24);
		central.writeUInt16LE(nameBytes.length, 28);
		central.writeUInt16LE(0, 30); // extra
		central.writeUInt16LE(0, 32); // comment
		central.writeUInt16LE(0, 34); // disk number
		central.writeUInt16LE(0, 36); // internal attrs
		central.writeUInt32LE(0, 38); // external attrs
		central.writeUInt32LE(offset, 42);
		nameBytes.copy(central, 46);

		localParts.push(local, compressed);
		centralParts.push(central);
		offset += local.length + compressed.length;
	}

	const centralDir = Buffer.concat(centralParts);
	const end = Buffer.alloc(22);
	end.writeUInt32LE(0x06054b50, 0);
	end.writeUInt16LE(0, 4);
	end.writeUInt16LE(0, 6);
	end.writeUInt16LE(entries.length, 8);
	end.writeUInt16LE(entries.length, 10);
	end.writeUInt32LE(centralDir.length, 12);
	end.writeUInt32LE(offset, 16);
	end.writeUInt16LE(0, 20);

	return Buffer.concat([...localParts, centralDir, end]);
}

/* ------------------------------------------------------------------ */
/* Run                                                                */
/* ------------------------------------------------------------------ */

const cwd = process.cwd();
const outDir = join(cwd, PROJECT_NAME);
const zipPath = join(cwd, `${PROJECT_NAME}.zip`);

const written = writeProject(outDir);

const entries = Object.keys(FILES)
	.sort()
	.map((rel) => ({ name: `${PROJECT_NAME}/${rel}`, data: FILES[rel] }));

const zip = createZip(entries);
writeFileSync(zipPath, zip);

const kb = (zip.length / 1024).toFixed(1);
console.log(`Wrote ${written} files to ${PROJECT_NAME}/`);
console.log(`Created ${PROJECT_NAME}.zip (${kb} KB, ${entries.length} entries)`);
